 const html='"\\'.repeat(1800)+' Tiếng Việt 𠮷',groups=['a.test','b.test'].map(site=>({id:site,site,role:'article',failures:[{url:'https://'+site+'/original?x=1&y=2',error:'missing_title'}],samples:Array.from({length:4},(_,i)=>({url:'https://'+site+'/article-'+i,kind:i<2?'fail':'good',html}))})),before=JSON.stringify(groups);assert(Buffer.byteLength(before)>AI_REVIEW_MAX_BYTES);
 const packed=packAiReviewGroups(groups);assert.equal(packed.batches.length,1);assert.equal(packed.skipped.length,0);const batch=packed.batches[0];assert(batch.inputBytes<=AI_REVIEW_MAX_BYTES);assert.equal(batch.inputBytes,Buffer.byteLength(JSON.stringify(batch.groups)));assert.equal(batch.groups.length,2);for(let n=0;n<2;n++){assert.equal(batch.groups[n].samples.filter(s=>s.kind==='fail').length,2);assert.deepEqual(batch.groups[n].samples.map(s=>s.url),groups[n].samples.map(s=>s.url));assert(batch.groups[n].samples.every(s=>!s.html.includes('\uFFFD')));}assert.equal(JSON.stringify(groups),before);
